      "section": "7.3",
      "label": "(1)",
      "text": "The PCA pump shall continue to infuse for 10 minutes during interruption of mains electricity supply using battery backup131, either continuously or spread over an hour. (Five minutes to recharge per minute using battery.)",
      "id": null
    },
    {
      "section": "7.3",
      "label": "(2)",
      "text": "The user interface must show that the PCA pump is working on battery backup, and an estimate of the number of minutes of battery-powered infusion remain. 132",
      "id": null
    },
    {
      "section": "7.3",
      "label": "(3)",
      "text": "The estimate of remaining battery energy must be accurate to within Xbtty = 25%.133",
      "id": null
    },
    {
      "section": "7.3",
      "label": "(4)",
      "text": "If the estimated battery life remaining is less than ∆ lba = 3 minutes, the pump shall issue a low-battery warning 134.",
      "id": null
    },
    {
      "section": "7.3",
      "label": "(5)",
      "text": "The PCA pump shall detect battery failure and issue a battery failure alarm 135.",
      "id": null
    },
    {
      "section": "7.3",
      "label": "(6)",
      "text": "The PCA pump shall detect power supply voltage out-of-range, issue a voltage out-of-range warning 136, and switch to battery backup when out-of-range.",
      "id": null
