    {
      "section": "7.3",
      "label": "(9)",
      "text": "The PCA pump must be electromagnetically compatible 139 according to IEC 60601-1-2 (2001) Medical Electrical Equipment, Part 1: General Requirements for Safety, 2. Collateral Standard: Electromagnetic Compatibility - Requirements and Tests . (IEC 60601-1-2 2.3.1)",
      "id": null
    },
    {
      "section": "7.3",
      "label": "(10)",
      "text": "The PCA pump must withstand electrostatic discharge140.",
